from __future__ import annotations
from itertools import product
from typing import Callable, FrozenSet, List

World = FrozenSet[str]
Relation = Callable[[World, World], bool]

def all_worlds(atoms: List[str]) -> List[World]:
    return [frozenset(a for a, b in zip(atoms, bits) if b)
            for bits in product([False, True], repeat=len(atoms))]

def reflexive(R: Relation, M: List[World]) -> bool:
    return all(R(w, w) for w in M)
def transitive(R: Relation, M: List[World]) -> bool:
    return all((not (R(w,v) and R(v,u))) or R(w,u) for w in M for v in M for u in M)
def directed(R: Relation, M: List[World]) -> bool:
    return all(any(R(v1,u) and R(v2,u) for u in M)
               for w in M for v1 in M for v2 in M if R(w,v1) and R(w,v2))

def box_true(R, M, w, S: FrozenSet[World]) -> bool:
    """S is the set of worlds where an abstract proposition p holds; is Box p true at w?"""
    return all(v in S for v in M if R(w, v))
def dia_true(R, M, w, S) -> bool:
    return any(v in S for v in M if R(w, v))

if __name__ == "__main__":
    atoms = ["a", "b"]
    M = all_worlds(atoms)
    R = lambda w, v: True  # reflexive + transitive + directed
    print("reflexive", reflexive(R, M), "transitive", transitive(R, M), "directed", directed(R, M))
    # Enumerate every possible proposition (subset of worlds) and check the axioms.
    from itertools import chain, combinations
    subsets = list(chain.from_iterable(combinations(M, k) for k in range(len(M)+1)))
    T = all(box_true(R,M,w,frozenset(S)) <= (w in frozenset(S)) or True and
            (not box_true(R,M,w,frozenset(S)) or w in frozenset(S))
            for S in subsets for w in M)
    two = all((not dia_true(R,M,w,frozenset({v for v in M if box_true(R,M,v,frozenset(S))})))
              or box_true(R,M,w,frozenset({v for v in M if dia_true(R,M,v,frozenset(S))}))
              for S in subsets for w in M)
    print("Axiom T holds for every proposition:", T)
    print("Axiom .2 holds for every proposition:", two)

